'use strict';

function renderMeter(samples, width, filled = '#', empty = '-') {
  if (!Array.isArray(samples)) {
    throw new TypeError('samples must be an array');
  }
  if (!Number.isInteger(width)) {
    throw new TypeError('width must be an integer');
  }
  if (width < 0 || width > 1000) {
    throw new RangeError('width is out of range');
  }
  if (typeof filled !== 'string' || filled.length === 0) {
    throw new TypeError('filled must be a non-empty string');
  }
  if (typeof empty !== 'string' || empty.length === 0) {
    throw new TypeError('empty must be a non-empty string');
  }

  return samples.map((sample) => {
    if (typeof sample !== 'number' || !Number.isFinite(sample)) {
      throw new TypeError('each sample must be a finite number');
    }
    if (sample < 0 || sample > 1) {
      throw new RangeError('sample is out of range');
    }
    const count = Math.floor(sample * width);
    return filled.repeat(count) + empty.repeat(width - count) +
      ' ' + Math.round(sample * 100) + '%';
  });
}

module.exports = { renderMeter };

