'use strict';

const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Reflect.ownKeys(api), ['renderMeter']);
const { renderMeter } = api;

const samples = Object.freeze([0, 0.124, 0.5, 0.999, 1]);
assert.deepStrictEqual(renderMeter(samples, 10), [
  '---------- 0%',
  '#--------- 12%',
  '#####----- 50%',
  '########## 100%',
  '########## 100%'
]);
assert.deepStrictEqual(samples, [0, 0.124, 0.5, 0.999, 1]);

assert.deepStrictEqual(renderMeter([0.25, 0.5], 4, '[]', '..'), [
  '[]...... 25%',
  '[][].... 50%'
]);
assert.deepStrictEqual(renderMeter([0.5], 0), [' 50%']);
assert.deepStrictEqual(renderMeter([], 1000), []);

const first = renderMeter([0.5], 2);
const second = renderMeter([0.5], 2);
assert.notStrictEqual(first, second);
first.push('changed');
assert.deepStrictEqual(second, ['#- 50%']);

assert.throws(() => renderMeter('not-array', 2), TypeError);
assert.throws(() => renderMeter([null], 2), TypeError);
assert.throws(() => renderMeter([NaN], 2), TypeError);
assert.throws(() => renderMeter([Infinity], 2), TypeError);
assert.throws(() => renderMeter([-0.01], 2), RangeError);
assert.throws(() => renderMeter([1.01], 2), RangeError);
assert.throws(() => renderMeter([], '2'), TypeError);
assert.throws(() => renderMeter([], 1.5), TypeError);
assert.throws(() => renderMeter([], -1), RangeError);
assert.throws(() => renderMeter([], 1001), RangeError);
assert.throws(() => renderMeter([], 2, ''), TypeError);
assert.throws(() => renderMeter([], 2, '#', ''), TypeError);
assert.throws(() => renderMeter([], 2, 1, '-'), TypeError);
assert.throws(() => renderMeter([], 2, '#', null), TypeError);

